def point_in_triangle(p, a, b, c):
    # Function to compute the cross product of vectors (o, a) and (o, b)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Compute vectors from point p to the triangle vertices
    c1 = cross(p, a, b)
    c2 = cross(p, b, c)
    c3 = cross(p, c, a)

    # Check if the point is on the same side of all edges
    # (If all cross products have the same sign or are zero, the point is inside or on the edge)
    return (c1 >= 0 and c2 >= 0 and c3 >= 0) or (c1 <= 0 and c2 <= 0 and c3 <= 0)
