def is_point_on_segment(p, a, b):
    # Check if the point p lies on the line segment defined by a and b
    # The point is on the segment if:
    # 1. The cross product of vectors (b - a) and (p - a) is zero (collinear)
    # 2. The dot product of vectors (p - a) and (p - b) is <= 0 (p lies between a and b)

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def dot(a, b):
        return a[0] * b[0] + a[1] * b[1]

    # Check collinearity
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b
    if dot(p, p) > dot(a, a) + dot(b, b) or dot(p, p) < min(dot(a, a), dot(b, b)):
        return False

    return True
```

