def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Return the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    if all(cross_product(points[0], points[i], points[1]) == 0 for i in range(2, n)):
        return False

    # Determine the sign of the cross product to check consistency
    sign = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cp = cross_product(a, b, c)
        if cp == 0:
            continue  # Collinear points, still convex if others are okay
        if sign == 0:
            sign = 1 if cp > 0 else -1
        elif (sign > 0 and cp < 0) or (sign < 0 and cp > 0):
            return False  # Change in direction, not convex

    return True
```

