def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product of OA and OB vectors
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # A polygon must have at least 3 points

    # Check the sign of the cross product of consecutive edges
    sign = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_prod = cross(a, b, c)

        # Check if all cross products have the same sign
        if cross_prod == 0:
            return False  # Collinear points make it non-convex
        if sign == 0:
            sign = 1 if cross_prod > 0 else -1
        elif (sign > 0 and cross_prod < 0) or (sign < 0 and cross_prod > 0):
            return False  # Change in sign implies non-convex

    return True
```

