    if n < 3:
        return False  # A polygon must have at least 3 points

    def cross(o, a, b):
        # Compute the cross product of vectors (a - o) and (b - o)
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if all consecutive triplets have the same sign for the cross product
    sign = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_product = cross(a, b, c)
        if cross_product == 0:
            # If any three points are collinear, it's not convex
            return False
        if sign == 0:
            sign = 1 if cross_product > 0 else -1
        elif (cross_product > 0 and sign < 0) or (cross_product < 0 and sign > 0):
            return False
    return True
