def is_convex_polygon(points):
    def cross(p1, p2, p3):
        # Calculate the cross product of vectors (p2 - p1) and (p3 - p1)
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    n = len(points)
    if n < 3:
        return False

    # Check if all points are collinear
    first_cross = cross(points[0], points[1], points[2])
    if first_cross == 0:
        return False

    # Determine the sign of the first cross product to use as a reference
    sign = 1 if first_cross > 0 else -1

    for i in range(n):
        p1 = points[i]
        p2 = points[(i + 1) % n]
        p3 = points[(i + 2) % n]
        cross_prod = cross(p1, p2, p3)
        if cross_prod == 0:
            return False
        if (cross_prod > 0 and sign < 0) or (cross_prod < 0 and sign > 0):
            return False

    return True
