def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False  # A polygon must have at least 3 points

    def cross_product(o, a, b):
        # Returns the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check all consecutive triplets of points
    prev_cross = 0
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        cross = cross_product(o, a, b)

        if cross == 0:
            # Points are collinear, not a valid convex polygon
            return False

        if i == 0:
            prev_cross = cross
        elif (cross > 0 and prev_cross < 0) or (cross < 0 and prev_cross > 0):
            # The sign of the cross product changed, not convex
            return False
        prev_cross = cross

    return True
