def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - q)
        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check the sign of the cross product for consecutive triplets
    sign = 0
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        c = cross(p, q, r)
        if c == 0:
            return False  # Collinear points, not convex
        if i == 0:
            sign = 1 if c > 0 else -1
        elif (sign > 0 and c < 0) or (sign < 0 and c > 0):
            return False  # Change in direction, not convex
    return True
```

