def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is considered valid

    rows = len(grid)
    cols = len(grid[0])

    # Determine the expected values based on (i + j) % 2
    expected_values = set()
    for i in range(rows):
        for j in range(cols):
            if (i + j) % 2 == 0:
                expected_values.add(grid[i][j])
            else:
                expected_values.add(grid[i][j])

    # If more than two distinct values are used, it's not a checkerboard
    if len(expected_values) != 2:
        return False

    # Check if adjacent cells differ
    for i in range(rows):
        for j in range(cols):
            # Check right neighbor
            if j + 1 < cols and grid[i][j] == grid[i][j + 1]:
                return False
            # Check bottom neighbor
            if i + 1 < rows and grid[i][j] == grid[i + 1][j]:
                return False

    return True
```

