def parse_simple_expr(s):
    # Find the operator index
    for i, char in enumerate(s):
        if char in "+-*/":
            operator_index = i
            break

    # Split the expression into left and right operands
    left = int(s[:operator_index])
    right = int(s[operator_index+1:])
    operator = s[operator_index]

    # Perform the operation
    if operator == "+":
        return left + right
    elif operator == "-":
        return left - right
    elif operator == "*":
        return left * right
    elif operator == "/":
        return left / right
```

