def parse_url_parts(url):
    # Split the URL into the scheme and the rest
    if '://' not in url:
        raise ValueError("Invalid URL format: missing '://'")
    scheme, rest = url.split('://', 1)

    # Split the rest into host, path, and query
    host_part = rest.split('/', 1)
    host = host_part[0]

    if len(host_part) == 1:
        path = ''
        query = ''
    else:
        path_query = host_part[1]
        if '?' in path_query:
            path, query = path_query.split('?', 1)
        else:
            path = path_query
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

