def parse_env_line(line):
    # Split the line into key and value parts based on the first '='
    if '=' not in line:
        return (line, '')  # No '=' found, treat the whole line as key and empty string as value

    key, value_part = line.split('=', 1)

    # Check if the value is quoted
    if len(value_part) >= 2 and value_part[0] == value_part[-1] and value_part[0] in ('"', "'"):
        # Remove the surrounding quotes
        value = value_part[1:-1]
    else:
        value = value_part

    return (key, value)
```

