def intersection_car_pass_count(events, green_duration):
    passed = 0
    for tick, direction in events:
        if (tick // green_duration) % 2 == 0:
            # North-South green light
            if direction in ['N', 'S']:
                passed += 1
        else:
            # East-West green light
            if direction in ['E', 'W']:
                passed += 1
    return passed
```

