def shopping_cart_total(events):
    cart = {}  # Dictionary to store items: {item: (quantity, unit_price)}

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                current_qty, current_price = cart[item]
                # Update the quantity and price if the new price is different
                if current_price != price:
                    current_price = price
                current_qty += qty
                cart[item] = (current_qty, current_price)
            else:
                cart[item] = (qty, price)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart:
                current_qty, current_price = cart[item]
                if current_qty > qty:
                    cart[item] = (current_qty - qty, current_price)
                else:
                    del cart[item]
        elif event[0] == "clear":
            cart.clear()

    # Calculate total cost
    total = sum(qty * price for qty, price in cart.values())
    return total
