def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize the robot's position and direction
    x, y = 0, 0
    direction = "N"

    # Set of cleaned cells (including start position)
    cleaned = set((x, y))

    # Direction mapping: current direction -> (dx, dy)
    directions = {
        "N": (0, 1),
        "E": (1, 0),
        "S": (0, -1),
        "W": (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == "L":
            # Turn left (counter-clockwise)
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            elif direction == "E":
                direction = "N"
        elif cmd == "R":
            # Turn right (clockwise)
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd == "F":
            # Move forward if not in obstacle
            dx, dy = directions[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add the new position to cleaned cells
            cleaned.add((x, y))

    return len(cleaned)
```

