def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for O(1) lookup
    obstacle_set = set(obstacles)

    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'  # Starting direction is North

    # Directions: 'N' -> (0, 1), 'E' -> (1, 0), 'S' -> (0, -1), 'W' -> (-1, 0)
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Set to store cleaned cells
    cleaned_cells = set()
    cleaned_cells.add((x, y))  # Starting cell is cleaned

    for cmd in commands:
        if cmd == 'L':
            # Rotate counter-clockwise
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            elif direction == 'E':
                direction = 'N'
        elif cmd == 'R':
            # Rotate clockwise
            if direction == 'N':
                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            dx, dy = direction_map[direction]
            new_x = x + dx
            new_y = y + dy

            # Check if new position is an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y

        # Add current position to cleaned cells
        cleaned_cells.add((x, y))

    return len(cleaned_cells)
