def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    crossing_ticks = []
    current_tick = 0
    while current_tick < max(arrivals) + red_duration + green_duration:
        # Check if current_tick is in red phase
        if current_tick % (red_duration + green_duration) < red_duration:
            # Check for pedestrians who can cross now
            for i in range(len(arrivals)):
                if arrivals[i] <= current_tick and arrivals[i] not in crossing_ticks:
                    crossing_ticks.append(current_tick)
                    arrivals[i] = -1  # Mark as crossed
        current_tick += 1
    return crossing_ticks
```

