def undo_redo_state(commands):
    document = []
    redo_history = []

    for cmd in commands:
        if cmd[0] == "do":
            value = cmd[1]
            document.append(value)
            redo_history.clear()
        elif cmd[0] == "undo":
            if document:
                value = document.pop()
                redo_history.append(value)
        elif cmd[0] == "redo":
            if redo_history:
                value = redo_history.pop()
                document.append(value)

    return document
```

