def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Convert the requests list to a set for fast lookups
    request_set = set(requests)

    # Initialize the list of stops with the starting floor if it is requested
    stops = []
    if start_floor in request_set:
        stops.append(start_floor)

    # Determine the range of floors to check based on direction
    if direction == 1:  # Going up
        for floor in range(start_floor + 1, top_floor + 1):
            if floor in request_set:
                stops.append(floor)
    else:  # Going down
        for floor in range(start_floor - 1, 0, -1):
            if floor in request_set:
                stops.append(floor)

    return stops
```

