def light_switch_group(n, events):
    # Initialize all lights to off (False)
    lights = [False] * n
    toggle_count = 0  # To track the number of toggles for each light

    for event in events:
        if event[0] == "toggle":
            index = event[1]
            toggle_count += 1
            # If the number of toggles is odd, the light is on; else, it is off
            lights[index] = (toggle_count % 2 == 1)
        elif event[0] == "toggle_all":
            toggle_count += 1
            # Toggle all lights based on the count of toggles
            for i in range(n):
                lights[i] = (toggle_count % 2 == 1)
        elif event[0] == "reset":
            # Reset all lights to off
            toggle_count = 0
            for i in range(n):
                lights[i] = False

    return lights
```

