def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    red_a, green_a, yellow_a = durations_a
    red_b, green_b, yellow_b = durations_b
    cycle_a = red_a + green_a + yellow_a
    cycle_b = red_b + green_b + yellow_b

    count = 0

    for t in range(n_ticks):
        # Determine the state of light A at tick t
        state_a = (t % cycle_a)
        if state_a < red_a:
            light_a = "RED"
        elif state_a < red_a + green_a:
            light_a = "GREEN"
        elif state_a < red_a + green_a + yellow_a:
            light_a = "YELLOW"
        else:
            light_a = "RED"

        # Determine the state of light B at tick t
        state_b = (t % cycle_b)
        if state_b < red_b:
            light_b = "RED"
        elif state_b < red_b + green_b:
            light_b = "GREEN"
        elif state_b < red_b + green_b + yellow_b:
            light_b = "YELLOW"
        else:
            light_b = "RED"

        # Count if both are green
        if light_a == "GREEN" and light_b == "GREEN":
            count += 1

    return count
```

