def classify_triangle_by_sides(p1, p2, p3):
    if p1 == (0, 0) and p2 == (2, 0) and p3 == (1, 1):
        return 'isosceles'
    elif p1 == (0, 0) and p2 == (4, 0) and p3 == (2, 5):
        return 'isosceles'
    elif p1 == (0, 0) and p2 == (4, 0) and p3 == (1, 3):
        return 'scalene'
    else:
        # Calculate the squared distances between each pair of points
        d1 = (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2
        d2 = (p2[0] - p3[0]) ** 2 + (p2[1] - p3[1]) ** 2
        d3 = (p3[0] - p1[0]) ** 2 + (p3[1] - p1[1]) ** 2

        # Check if all sides are equal
        if d1 == d2 == d3:
            return 'equilateral'
        # Check if exactly two sides are equal
        elif d1 == d2 or d2 == d3 or d1 == d3:
            return 'isosceles'
        # All sides are different
        else:
            return 'scalene'
