        return True

    # Check if the grids are empty
    if not grid1 or not grid2:
        return True

    # Check if the grids have the same dimensions
    if len(grid1) != len(grid2) or len(grid1[0]) != len(grid2[0]):
        return False

    # Check for 90-degree rotation
    if len(grid1) == len(grid1[0]):
        rotated_90 = [[grid1[len(grid1) - j - 1][i] for j in range(len(grid1))] for i in range(len(grid1[0]))]
        if rotated_90 == grid2:
            return True

    # Check for 180-degree rotation
    rotated_180 = [[grid1[len(grid1) - i - 1][len(grid1[0]) - j - 1] for j in range(len(grid1[0]))] for i in range(len(grid1))]
    if rotated_180 == grid2:
