            from_acct, to_acct, amount = event[1], event[2], event[3]
            if balances.get(from_acct, 0) >= amount:
                balances[from_acct] = balances.get(from_acct, 0) - amount
                balances[to_acct] = balances.get(to_acct, 0) + amount

