    for event in events:
        if event[0] == 'add':
            item = event[1]
            qty = event[2]
            price = event[3]
            if item in cart:
                cart[item] = (cart[item][0] + qty, cart[item][1])
            else:
                cart[item] = (qty, price)
        elif event[0] == 'remove':
            item = event[1]
            qty = event[2]
            if item in cart:
                if cart[item][0] > qty:
                    cart[item] = (cart[item][0] - qty, cart[item][1])
                else:
                    del cart[item]
        elif event[0] == 'clear':
            cart = {}
    total = 0
    for item in cart:
        total += cart[item][0] * cart[item][1]
    return total
