            'N': (0, 1),
            'E': (1, 0),
            'S': (0, -1),
            'W': (-1, 0)
        }

        # Process commands
        for cmd in commands:
            if cmd == 'L':
                # Counter-clockwise turn
                if direction == 'N':
                    direction = 'W'
                elif direction == 'W':
                    direction = 'S'
                elif direction == 'S':
                    direction = 'E'
                else:  # 'E'
