                    direction = 'E'
                elif direction == 'E':
                    direction = 'S'
                elif direction == 'S':
                    direction = 'W'
                else:  # 'W'
                    direction = 'N'
            elif cmd == 'F':
                dx, dy = dir_map[direction]
                new_x, new_y = x + dx, y + dy
                # Check if the new position is an obstacle
                if (new_x, new_y) not in obstacles:
                    x, y = new_x, new_y
                # Add new position to cleaned cells
                cleaned.add((x, y))

        return len(cleaned)
